insert into public.projects (id, position, published, featured, title, summary, cat, cat_label, year, tag, tags, url, img, c1, c2, challenge, role, stack, deliver, article) values
  ('copiloto', 0, true, false, 'Copiloto de atendimento', 'Assistente que sugere respostas para agentes de suporte, mostra a fonte de cada sugestão e nunca envia nada sem revisão humana.', 'produto', 'Produto', '2026', 'Sugestão · revisar', array['IA', 'UX', 'Frontend'], null, null, 'var(--aurora-violet-fill)', 'var(--aurora-blue-fill)', 'Agentes desconfiavam de respostas automáticas e acabavam reescrevendo tudo.', 'Direção de UX, prototipação com o modelo real e front-end dos componentes de sugestão.', 'Figma · React · TypeScript · API de LLM', array['Painel de sugestões com citações', 'Estados de confiança e de falha', 'Guia de escrita para o modelo'], '{"intro":"O time de suporte já tinha um modelo capaz de escrever boas respostas. O problema era outro: ninguém confiava nelas. Este projeto foi sobre desenhar a confiança, não a automação.","sections":[{"id":"contexto","title":"Contexto","body":["Os agentes atendiam várias conversas ao mesmo tempo e recebiam sugestões automáticas num campo de texto comum. Sem saber de onde vinha cada frase, a maioria apagava tudo e escrevia do zero.","A pergunta que guiou o trabalho foi simples: o que um agente precisa ver para aceitar uma sugestão sem medo?"]},{"id":"processo","title":"Processo","body":["Acompanhei turnos de atendimento e prototipei direto com o modelo real, e não com textos fixos. Assim, os testes mostravam os erros de verdade do modelo, e não uma versão idealizada dele.","Cada rodada de teste gerava ajustes em duas frentes ao mesmo tempo: a interface e as instruções dadas ao modelo."],"figure":{"src":"","caption":"Primeiros protótipos: sugestão com a fonte sempre visível ao lado."}},{"id":"solucao","title":"Solução","body":["Cada sugestão aparece com a citação do artigo da base de conhecimento que a originou. O agente pode aceitar, editar trechos ou descartar, e nada é enviado sem uma ação explícita dele.","Quando o modelo não encontra fonte suficiente, a interface diz isso claramente em vez de inventar uma resposta."],"figure":{"src":"","caption":"Painel final com citações, estados de confiança e ações de revisão."}},{"id":"aprendizados","title":"Aprendizados","body":["Transparência vale mais do que precisão escondida. Uma sugestão imperfeita, mas com a fonte à vista, era mais usada do que uma perfeita sem explicação."]}]}'::jsonb),
  ('lumen', 1, true, false, 'Lumen DS', 'Design system com tokens exportados do Figma e componentes prontos para os estados que interfaces com IA exigem.', 'sistema', 'Design system', '2025', 'Token · sincronizado', array['Design system', 'Frontend', 'IA'], null, null, 'var(--aurora-mint-fill)', 'var(--aurora-blue-fill)', 'Cada time inventava seu próprio "carregando", "incerto" e "erro do modelo".', 'Arquitetura de tokens, biblioteca de componentes e documentação.', 'Figma Variables · Style Dictionary · React', array['Pipeline de tokens Figma → CSS', 'Componentes de streaming e citação', 'Site de documentação'], '{"intro":"Produtos com IA têm estados que os design systems tradicionais não cobrem: resposta sendo escrita, resposta incerta, modelo indisponível. O Lumen nasceu para dar um nome e um componente a cada um deles.","sections":[{"id":"contexto","title":"Contexto","body":["Vários times lançavam recursos com IA ao mesmo tempo, e cada um resolvia do seu jeito os mesmos estados. O resultado era um produto que se comportava de forma diferente em cada tela."]},{"id":"processo","title":"Processo","body":["Comecei com um inventário de todas as telas com IA em produção e agrupei os estados que se repetiam. Depois, defini os tokens no Figma e montei um pipeline que os exporta automaticamente para CSS.","Os componentes foram construídos junto com os times que iam usá-los, em sessões curtas de revisão."],"figure":{"src":"","caption":"Inventário de estados de IA encontrados nas telas existentes."}},{"id":"solucao","title":"Solução","body":["A biblioteca inclui componentes de texto em streaming, citação de fonte, indicador de incerteza e falha do modelo, todos documentados com exemplos de uso e de quando não usar.","Uma mudança de token no Figma chega ao código sem trabalho manual."],"figure":{"src":"","caption":"Componentes de streaming e citação no site de documentação."}},{"id":"aprendizados","title":"Aprendizados","body":["Documentar quando não usar um componente evitou mais problemas do que documentar como usá-lo."]}]}'::jsonb),
  ('prompt-studio', 2, true, false, 'Prompt Studio', 'Ambiente para times de produto versionarem, testarem e compararem prompts lado a lado antes de ir para produção.', 'ferramenta', 'Ferramenta interna', '2025', 'Prompt · v12', array['IA', 'Frontend', 'Ferramenta'], null, null, 'var(--aurora-peach-fill)', 'var(--aurora-violet-fill)', 'Prompts viviam em planilhas e mudanças quebravam fluxos sem ninguém perceber.', 'Pesquisa com times internos, desenho da ferramenta e implementação do comparador.', 'React · TypeScript · Node', array['Histórico de versões com diff', 'Comparação de saídas lado a lado', 'Conjuntos de teste reutilizáveis'], '{"intro":"Um prompt é código de produto, mas era tratado como anotação. O Prompt Studio deu aos times um lugar para escrever, testar e comparar prompts com o mesmo cuidado que têm com o código.","sections":[{"id":"contexto","title":"Contexto","body":["Os prompts ficavam em planilhas e documentos soltos. Quando alguém mudava uma frase, não havia como saber o que tinha mudado nem se o resultado tinha piorado."]},{"id":"processo","title":"Processo","body":["Entrevistei pessoas de produto, engenharia e conteúdo que escreviam prompts no dia a dia. O ponto em comum era a falta de uma forma rápida de comparar duas versões."],"figure":{"src":"","caption":"Mapa do fluxo atual de edição de prompts, antes da ferramenta."}},{"id":"solucao","title":"Solução","body":["A ferramenta guarda cada versão com um diff legível e roda o mesmo conjunto de entradas em duas versões, mostrando as saídas lado a lado.","Os conjuntos de teste podem ser salvos e reaproveitados por outros times."],"figure":{"src":"","caption":"Comparador com as saídas de duas versões lado a lado."}},{"id":"aprendizados","title":"Aprendizados","body":["A funcionalidade mais usada não foi a mais complexa: foi o diff simples entre versões."]}]}'::jsonb),
  ('confianca', 3, true, false, 'Quando confiamos na IA', 'Estudo qualitativo sobre quando as pessoas aceitam, revisam ou descartam sugestões automáticas no trabalho.', 'pesquisa', 'Pesquisa', '2024', 'Aceitar · editar · descartar', array['IA', 'UX', 'Pesquisa'], null, null, 'var(--aurora-rose-fill)', 'var(--aurora-mint-fill)', 'O time não sabia por que sugestões corretas eram ignoradas.', 'Planejamento, entrevistas, testes de usabilidade e síntese.', 'Entrevistas · Testes moderados · Figma', array['Relatório de achados', 'Princípios de transparência', 'Padrões de interface recomendados'], '{"intro":"Sugestões corretas estavam sendo ignoradas. Este estudo investigou o porquê e transformou os achados em princípios que os times de produto pudessem aplicar.","sections":[{"id":"contexto","title":"Contexto","body":["Os dados de uso mostravam o que as pessoas faziam com as sugestões, mas não explicavam por quê. Faltava ouvir quem usava."]},{"id":"processo","title":"Processo","body":["Conduzi entrevistas e testes moderados com pessoas de áreas diferentes, pedindo que pensassem em voz alta enquanto decidiam aceitar, editar ou descartar uma sugestão."],"figure":{"src":"","caption":"Síntese das sessões agrupada por momento de decisão."}},{"id":"solucao","title":"Achados","body":["A confiança dependia menos da qualidade da sugestão e mais de entender de onde ela vinha e quanto custava corrigir um erro.","Os achados viraram um conjunto de princípios de transparência e padrões de interface recomendados."],"figure":{"src":"","caption":"Padrões de interface recomendados a partir dos achados."}},{"id":"aprendizados","title":"Aprendizados","body":["Pesquisa só muda produto quando chega em formato de decisão. Por isso, cada achado saiu acompanhado de um padrão pronto para usar."]}]}'::jsonb),
  ('triagem', 4, true, false, 'Painel de triagem clínica', 'Interface que organiza a fila de exames com apoio de IA e deixa claro o nível de confiança de cada recomendação.', 'produto', 'Produto', '2024', 'Prioridade · alta', array['IA', 'UX', 'Saúde'], null, null, 'var(--aurora-blue-fill)', 'var(--aurora-mint-fill)', 'Profissionais precisavam de rapidez sem perder o controle da decisão final.', 'Desenho de interação, sistema de prioridade visual e protótipo de alta fidelidade.', 'Figma · React · Testes com especialistas', array['Fila priorizada com justificativas', 'Indicadores de confiança', 'Fluxo de contestação da recomendação'], '{"intro":"Na saúde, a IA pode sugerir, mas quem decide é o profissional. O painel precisava acelerar a triagem sem nunca esconder essa responsabilidade.","sections":[{"id":"contexto","title":"Contexto","body":["A fila de exames era organizada por ordem de chegada. Um modelo podia estimar a prioridade de cada caso, mas uma recomendação sem explicação não seria aceita pelos especialistas."]},{"id":"processo","title":"Processo","body":["Desenhei o fluxo junto com profissionais de saúde, em sessões curtas de teste com protótipos de alta fidelidade. O foco era entender que informação eles precisavam para concordar ou discordar da recomendação."],"figure":{"src":"","caption":"Estudos de hierarquia visual para a fila priorizada."}},{"id":"solucao","title":"Solução","body":["Cada caso mostra a prioridade sugerida, a justificativa e o nível de confiança. O profissional pode contestar a recomendação em um passo, e essa contestação fica registrada."],"figure":{"src":"","caption":"Fila com justificativas e fluxo de contestação."}},{"id":"aprendizados","title":"Aprendizados","body":["Dar um caminho fácil para discordar aumentou a disposição dos especialistas para usar a recomendação."]}]}'::jsonb),
  ('onboarding', 5, true, false, 'Onboarding adaptativo', 'Fluxo de entrada que se ajusta ao perfil da pessoa a partir das primeiras respostas, sem formulários longos.', 'produto', 'Produto', '2023', 'Passo 2 de 4', array['UX', 'Mobile', 'Frontend'], null, null, 'var(--aurora-lilac-fill)', 'var(--aurora-peach-fill)', 'Um único onboarding servia mal a perfis muito diferentes.', 'Estratégia de conteúdo, fluxos ramificados e implementação das telas.', 'React · TypeScript · Analytics', array['Árvore de perguntas adaptativa', 'Microcópia por perfil', 'Componentes de progresso'], '{"intro":"Perfis muito diferentes passavam pelo mesmo onboarding longo. A proposta foi fazer poucas perguntas no início e adaptar o resto do caminho a partir delas.","sections":[{"id":"contexto","title":"Contexto","body":["O fluxo de entrada tinha um formulário único para todos. Quem só queria experimentar o produto precisava responder as mesmas perguntas de quem ia configurar uma conta inteira."]},{"id":"processo","title":"Processo","body":["Mapeei os perfis de entrada e desenhei uma árvore de perguntas em que cada resposta elimina as perguntas que não fazem sentido para aquela pessoa."],"figure":{"src":"","caption":"Árvore de perguntas com os ramos por perfil."}},{"id":"solucao","title":"Solução","body":["O onboarding começa com duas perguntas e se ajusta a partir delas. A microcópia muda conforme o perfil, e o indicador de progresso mostra só os passos que aquela pessoa vai realmente ver."],"figure":{"src":"","caption":"Telas do fluxo com progresso adaptado ao perfil."}},{"id":"aprendizados","title":"Aprendizados","body":["Mostrar só os passos reais no indicador de progresso fez o fluxo parecer mais curto, mesmo quando não era."]}]}'::jsonb)
insert into public.articles (id, position, published, date, read_min, tags, img, c1, c2, tag, project, title, summary, intro, sections) values
  ('desenhar-confianca', 0, true, '2026-08-18', 7, array['IA', 'UX', 'Pesquisa'], null, 'var(--aurora-violet-fill)', 'var(--aurora-blue-fill)', 'Fonte · citada', 'copiloto', 'Desenhar confiança, não automação', 'Por que mostrar de onde vem cada resposta de um modelo muda mais a adoção do que melhorar a própria resposta.', 'Quase todo produto com IA começa pela pergunta “o que o modelo consegue fazer?”. Nos projetos em que trabalhei, a pergunta que destravou a adoção foi outra: “o que a pessoa precisa ver para aceitar o que o modelo fez?”.', '[{"id":"o-problema","title":"O problema não era a qualidade","body":["Em mais de um projeto, o modelo já escrevia respostas boas o bastante. Mesmo assim, as pessoas apagavam tudo e começavam do zero. Não por teimosia: sem saber de onde vinha cada frase, aceitar a sugestão era assumir um risco que não era delas.","Melhorar o modelo não resolvia isso. Uma resposta melhor, mas igualmente opaca, continuava sendo descartada."]},{"id":"mostrar-a-fonte","title":"Mostrar a fonte muda o comportamento","body":["A mudança mais eficaz foi também a mais simples: cada sugestão passou a vir acompanhada do trecho que a originou. Com a fonte ao lado, a pessoa deixa de avaliar “a IA” e passa a avaliar um argumento.","Isso também muda o erro. Quando o modelo se engana, o erro fica visível na comparação com a fonte, em vez de passar despercebido."],"quote":"Com a fonte ao lado, a pessoa deixa de avaliar “a IA” e passa a avaliar um argumento.","figure":{"src":"","caption":"Sugestão com a citação sempre visível, e não escondida num menu."}},{"id":"dizer-nao-sei","title":"Deixar o modelo dizer “não sei”","body":["O segundo passo foi desenhar o estado de falta de evidência. Quando não há fonte suficiente, a interface diz isso com clareza, em vez de preencher o espaço com uma resposta plausível.","Parece uma perda, mas é o que dá credibilidade às respostas que aparecem."]},{"id":"o-que-levo","title":"O que levo para outros projetos","body":["Confiança é um requisito de interface, não um efeito colateral da precisão. Ela precisa de estados próprios, de texto próprio e de testes próprios, e isso entra no planejamento desde o primeiro protótipo."]}]'::jsonb),
  ('prototipar-com-modelo-real', 1, true, '2026-06-02', 6, array['IA', 'UX', 'Frontend'], null, 'var(--aurora-peach-fill)', 'var(--aurora-violet-fill)', 'Protótipo · ao vivo', 'prompt-studio', 'Prototipar com o modelo real desde o primeiro dia', 'Textos fixos em protótipos de IA escondem justamente os casos que mais precisam de design: os erros.', 'Um protótipo de IA com respostas escritas à mão testa uma versão idealizada do produto. Os problemas de verdade aparecem quando o modelo real responde, com toda a sua variação.', '[{"id":"por-que","title":"Por que abandonar o texto fixo","body":["Respostas fixas são sempre bem formatadas, no tamanho certo e sem ambiguidade. O modelo real, não. Ele responde longo demais, curto demais, fora do tom ou com uma certeza que não deveria ter.","Se o protótipo não mostra esses casos, o teste com usuários também não mostra, e eles chegam direto na produção."]},{"id":"como","title":"Como monto esses protótipos","body":["Uso um front-end leve, ligado à API do modelo, com as instruções guardadas num arquivo que o time inteiro consegue editar. Assim, design e instruções evoluem juntos a cada rodada.","Cada sessão de teste fica registrada com a resposta que a pessoa viu, para que a discussão seja sobre o caso real, e não sobre a lembrança dele."],"figure":{"src":"","caption":"Protótipo ligado ao modelo, com as instruções editáveis ao lado."}},{"id":"cuidados","title":"Cuidados","body":["Protótipo ligado a modelo real precisa de dados de teste que não exponham informações sensíveis, e de um aviso claro para quem participa de que as respostas são geradas."]}]'::jsonb),
  ('tokens-para-agentes', 2, true, '2026-03-12', 8, array['Design system', 'Frontend', 'IA'], null, 'var(--aurora-mint-fill)', 'var(--aurora-blue-fill)', 'Token · semântico', 'lumen', 'Design tokens que agentes de código conseguem ler', 'Nomes semânticos e regras escritas junto dos tokens fazem ferramentas de IA gerarem interfaces coerentes com o sistema.', 'Quando uma ferramenta de IA escreve código de interface, ela usa o que encontra no repositório. Se os tokens forem uma lista de cores sem contexto, o resultado será uma interface com cores certas nos lugares errados.', '[{"id":"nomes","title":"Nomes que explicam o uso","body":["Um token chamado azul-500 diz qual é a cor. Um token chamado botao-primario-fundo diz onde ela vai. Para uma pessoa, a diferença é conveniência; para um agente de código, é a diferença entre acertar e adivinhar.","Por isso organizo os tokens em duas camadas: a base, com os valores, e a de papel, com o uso de cada um."]},{"id":"regras","title":"Regras escritas ao lado dos tokens","body":["Cada grupo de tokens ganha uma nota curta em texto: quando usar, quando não usar e qual é o par esperado. Essas notas ficam no mesmo arquivo, onde a ferramenta as encontra sem precisar de contexto extra."],"quote":"Para um agente de código, o nome do token é a diferença entre acertar e adivinhar."},{"id":"revisao","title":"Revisão continua humana","body":["Tokens bem descritos reduzem o retrabalho, mas não substituem a revisão. O código gerado passa pelo mesmo processo de revisão de qualquer outra contribuição."],"figure":{"src":"","caption":"Duas camadas de tokens: valores de base e papéis de uso."}}]'::jsonb),
  ('estados-de-erro-em-ia', 3, true, '2025-11-20', 5, array['IA', 'UX', 'Acessibilidade'], null, 'var(--aurora-blue-fill)', 'var(--aurora-mint-fill)', 'Estado · incerto', 'triagem', 'Os estados que ninguém desenha em produtos de IA', 'Carregando, incerto, parcial, recusado: um inventário dos estados que fazem falta quando o modelo não responde como o esperado.', 'Interfaces tradicionais têm poucos estados: vazio, carregando, sucesso e erro. Produtos com IA têm vários outros, e a maioria deles só é descoberta depois do lançamento.', '[{"id":"inventario","title":"Um inventário mínimo","body":["Começo todo projeto listando os estados antes de desenhar a tela principal: resposta em andamento, resposta parcial, baixa confiança, sem evidência, recusa por política e falha técnica.","Cada um precisa de texto próprio e de uma ação clara para a pessoa seguir."]},{"id":"acessibilidade","title":"Estados também precisam ser acessíveis","body":["Respostas que chegam aos poucos precisam ser anunciadas por leitores de tela sem repetir o texto inteiro a cada atualização. E níveis de confiança não podem depender só de cor."],"figure":{"src":"","caption":"Inventário de estados, do carregamento à recusa."}},{"id":"teste","title":"Como testo","body":["Forço cada estado no protótipo, com instruções que levam o modelo a falhar de propósito. É mais rápido do que esperar o erro aparecer sozinho."]}]'::jsonb),
  ('pesquisa-com-usuarios-de-ia', 4, true, '2025-07-08', 6, array['Pesquisa', 'UX', 'IA'], null, 'var(--aurora-rose-fill)', 'var(--aurora-mint-fill)', 'Entrevista · sessão 4', 'confianca', 'O que muda ao pesquisar com usuários de IA', 'Respostas que variam a cada sessão pedem outro roteiro de teste, outro registro e outra forma de analisar.', 'Num teste de usabilidade comum, todo participante vê a mesma tela. Com IA, cada pessoa pode ver uma resposta diferente para a mesma pergunta, e isso muda o jeito de planejar e de analisar a pesquisa.', '[{"id":"roteiro","title":"Roteiro por tarefa, não por tela","body":["Em vez de guiar a pessoa por telas, descrevo tarefas e deixo que ela chegue lá do jeito dela. O que observo é a decisão de aceitar, editar ou descartar o que o modelo produziu."]},{"id":"registro","title":"Registrar o que foi visto","body":["Guardo a resposta exata que cada participante recebeu. Sem isso, a análise mistura reações a respostas diferentes como se fossem a mesma coisa."],"quote":"Sem guardar a resposta exata, a análise mistura reações diferentes como se fossem a mesma."},{"id":"analise","title":"Analisar decisões","body":["O resultado mais útil costuma ser um mapa de quando as pessoas confiam, quando desconfiam e o que as faz mudar de ideia no meio da tarefa."],"figure":{"src":"","caption":"Mapa de decisões: aceitar, editar ou descartar."}}]'::jsonb),
  ('handoff-com-codigo', 5, true, '2025-02-14', 4, array['Design system', 'Frontend', 'Processo'], null, 'var(--aurora-lilac-fill)', 'var(--aurora-peach-fill)', 'Handoff · componente', 'lumen', 'Handoff é uma conversa, não um arquivo', 'Entregar componentes funcionando, e não só telas, encurta a distância entre design e produção.', 'Por muito tempo, a entrega de design foi um arquivo com telas e anotações. Hoje prefiro entregar componentes que já rodam, com os estados documentados, e usar as telas só como mapa.', '[{"id":"componentes","title":"Componentes no lugar de telas","body":["Quando o componente já existe em código, a discussão deixa de ser “está igual ao arquivo?” e passa a ser “funciona em todos os casos?”. É uma conversa bem mais útil."]},{"id":"rituais","title":"Rituais curtos","body":["Uma revisão curta e frequente com quem desenvolve vale mais do que uma especificação longa. Os ajustes pequenos acontecem na hora, e os grandes aparecem cedo."]}]'::jsonb),
  ('onboarding-que-se-adapta', 6, true, '2024-09-30', 5, array['UX', 'Mobile', 'Processo'], null, 'var(--aurora-peach-fill)', 'var(--aurora-rose-fill)', 'Passo 2 de 4', 'onboarding', 'Onboarding que se adapta a quem chega', 'Perguntar pouco, no momento certo, e pular o que a pessoa já sabe: notas de um onboarding mobile.', 'Onboardings longos tentam explicar tudo antes de a pessoa precisar de qualquer coisa. Neste projeto, a proposta foi o contrário: mostrar só o que ajuda no primeiro uso e deixar o resto aparecer quando fizer sentido.', '[{"id":"perguntar-pouco","title":"Perguntar pouco","body":["Uma única pergunta no início, sobre o objetivo da pessoa, já permitia pular metade das telas. O resto das informações era pedido só quando uma função precisava delas."]},{"id":"mobile","title":"Pensado para uma mão","body":["Ações principais ao alcance do polegar, textos curtos e a opção de sair a qualquer momento sem perder o que já foi preenchido."],"figure":{"src":"","caption":"Fluxo adaptativo: telas que aparecem conforme o objetivo escolhido."}}]'::jsonb)
insert into public.timeline (position, kind, period, title, org, description, title_full)
insert into public.site_content (key, value) values
  ('hero_bubbles', '[{"value":"UX","label":"Processos","tags":[{"label":"Lean Inception","icon":"i-sparkle"},{"label":"Double Diamond","icon":"i-book"},{"label":"Design Thinking","icon":"i-globe"},{"label":"Figma","icon":"i-bolt"},{"label":"Vision Design","icon":"i-school"},{"label":"Prototipação com IA","icon":"i-bot"}]},{"value":"1.5M","label":"de usuários impactados","tags":[{"label":"Sistemas SIGAD","icon":"i-archive"},{"label":"Grupo S","icon":"i-building"},{"label":"Sistemas jurídicos","icon":"i-scale"},{"label":"Sistemas normativos","icon":"i-doc"},{"label":"Portal institucional","icon":"i-globe"},{"label":"Portal governamental","icon":"i-landmark"},{"label":"Gateway de pagamentos","icon":"i-card"},{"label":"Gerenciador escolar","icon":"i-school"}]},{"value":"Code","label":"Desenvolvedor mobile","tags":[{"label":"React Native","icon":"i-phone"},{"label":"JavaScript","icon":"i-js"},{"label":"Expo","icon":"i-expo"},{"label":"PostgreSQL","icon":"i-db"},{"label":"Supabase","icon":"i-bolt"},{"label":"React JS","icon":"i-atom"}]},{"value":"IA","label":"IA & Inovação","tags":[{"label":"LLMs","icon":"i-cpu"},{"label":"Prompt design","icon":"i-prompt"},{"label":"Agentes","icon":"i-bot"},{"label":"RAG","icon":"i-book"},{"label":"Estratégia de produto","icon":"i-target"},{"label":"IA UX Design","icon":"i-sparkle"}]}]'::jsonb),
  ('services', '[{"title":"Pesquisa e UX Design","text":"Entendo usuários e mercado, desenho os fluxos e valido cada decisão com testes antes que ela chegue ao desenvolvimento.","items":["Pesquisa de usuários e mercado","Wireframes e testes de usabilidade","Testes de acessibilidade"]},{"title":"Engenharia de UX","text":"Construo protótipos front-end funcionais e escaláveis, prontos para integrar com o backend, que aceleram validações e o ciclo de desenvolvimento.","items":["React e React Native","Protótipos prontos para API","Integração com Supabase"]},{"title":"Design systems","text":"Guias de estilo, componentes e documentação que mantêm design e desenvolvimento falando a mesma língua.","items":["Guias de estilo e componentes","Prototipagem avançada no Figma","Documentação para o time de dev"]}]'::jsonb),
  ('skills', '["Figma","Maze","React","React Native","Supabase","Design systems","Acessibilidade","Scrum"]'::jsonb),
  ('contact', '{"email":"vieirajjr@gmail.com","linkedin":"https://abrir.link/IjGTS","github":"","dribbble":""}'::jsonb)
